let playingEffect=null,effectTimeout=null,effectContext=null,effectGeneration=0;
if(typeof prefs.effectVolume!=='number')prefs.effectVolume=.2;
if(typeof prefs.effects!=='boolean')prefs.effects=true;
const recordings={cat:'cat',dog:'dog',bird:'bird',goose:'goose',car:'car',bus:'bus',helicopter:'helicopter',plane:'plane'};
const imitations={hen:['Gıt gıt gıdak.','Cluck cluck.'],horse:['İhaha.','Neigh.'],donkey:['A i, a i.','Hee haw.'],duck:['Vak vak.','Quack quack.'],cow:['Möö.','Moo.'],sheep:['Mee.','Baa.'],goat:['Mee.','Baa.']};
const representativeEffects=['ambulance','firetruck','police','truck','tractor','motorcycle','atv','excavator','dozer','ship','bicycle'];
function stopEffect(){effectGeneration++;clearTimeout(effectTimeout);effectTimeout=null;if(playingEffect){playingEffect.pause();playingEffect.currentTime=0;playingEffect=null}if(effectContext){effectContext.close().catch(()=>{});effectContext=null}const button=document.querySelector('#effectPlay');if(button)button.textContent=t('◖)) Sesini dinle','◖)) Hear its sound')}
const cancelBeforeEffects=cancelSpeech;
cancelSpeech=function(){stopEffect();cancelBeforeEffects()};
function effectType(id){return recordings[id]?'recording':imitations[id]?'imitation':representativeEffects.includes(id)?'example':null}
function playEffect(id){cancelSpeech();if(!prefs.effects)return;if(imitations[id]){speak(imitations[id][tr()?0:1]);return}if(recordings[id]){const currentEffect=++effectGeneration;const audio=new Audio(`sounds/${recordings[id]}.ogg`);playingEffect=audio;audio.volume=Math.max(0,Math.min(.5,prefs.effectVolume));audio.onended=()=>{if(currentEffect===effectGeneration)stopEffect()};audio.play().then(()=>{if(currentEffect!==effectGeneration){audio.pause();return}effectTimeout=setTimeout(stopEffect,3500)}).catch(error=>{if(currentEffect!==effectGeneration||error.name==='AbortError')return;stopEffect();const note=document.querySelector('#effectNote');if(note)note.textContent=t('Bu cihaz sesi çalamadı. Seslendirmeyi dinleyebilirsiniz.','This device could not play the sound. You can still hear the spoken name.')});return}const AudioClass=window.AudioContext||window.webkitAudioContext;if(!AudioClass)return;effectContext=new AudioClass();const context=effectContext,gain=context.createGain(),now=context.currentTime;gain.connect(context.destination);gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(Math.max(0,Math.min(.5,prefs.effectVolume))*.12,now+.15);gain.gain.setValueAtTime(Math.max(0,Math.min(.5,prefs.effectVolume))*.12,now+2.65);gain.gain.linearRampToValueAtTime(0,now+2.9);const oscillator=context.createOscillator();oscillator.connect(gain);oscillator.type='sine';if(['ambulance','firetruck','police'].includes(id)){const frequencies=id==='ambulance'?[620,830]:id==='firetruck'?[490,690]:[670,910];const step=id==='police'?.3:.55;for(let time=0;time<2.8;time+=step)oscillator.frequency.linearRampToValueAtTime(frequencies[Math.floor(time/step)%2],now+time)}else if(id==='bicycle'){oscillator.frequency.setValueAtTime(1250,now);gain.gain.exponentialRampToValueAtTime(.0001,now+1)}else if(id==='ship'){oscillator.frequency.setValueAtTime(150,now)}else{oscillator.type='triangle';oscillator.frequency.setValueAtTime(85,now);oscillator.frequency.linearRampToValueAtTime(135,now+1.5);oscillator.frequency.linearRampToValueAtTime(85,now+2.8)}oscillator.start();oscillator.stop(now+3);effectTimeout=setTimeout(stopEffect,3100);context.resume().catch(stopEffect)}
const lessonWithEffects=showLesson;
showLesson=function(id){lessonWithEffects(id);const kind=effectType(id);if(kind&&prefs.effects)$('.teaching-feature>div:last-child').insertAdjacentHTML('beforeend',`<div class="effect-actions"><button class="quiet" id="effectPlay">◖)) ${t('Sesini dinle','Hear its sound')}</button><button class="quiet" id="effectStop">■ ${t('Durdur','Stop')}</button></div><p id="effectNote" class="setting-note">${kind==='imitation'?t('Ses taklidi · konuşma sesiyle','Sound imitation · spoken voice'):kind==='example'?t('Kısa temsili ses · düşük sesle başlar','Short representative sound · starts softly'):t('Gerçek ses kaydı · kısa dinleme','Real recording · short playback')}</p>`);if($('#effectPlay'))$('#effectPlay').onclick=()=>playEffect(id);if($('#effectStop'))$('#effectStop').onclick=stopEffect};
const settingsWithEffects=settings;
settings=function(){settingsWithEffects();$('#saveSettings').insertAdjacentHTML('beforebegin',`<section class="level-card"><h3>${t('Hayvan ve araç sesleri','Animal and vehicle sounds')}</h3><label><input id="effectEnabled" type="checkbox" ${prefs.effects?'checked':''}> ${t('Sesini dinle düğmesini göster','Show the sound button')}</label><label for="effectVolume">${t('Efekt ses düzeyi · telefon sesini de düşük tutun','Effect volume · keep device volume low too')}</label><input id="effectVolume" type="range" min="0" max="0.5" step="0.05" value="${prefs.effectVolume}"><p class="setting-note">${t('Efektler yalnızca düğmeye dokununca çalar. Sirenler temsili ve kısadır. Bazı hayvanlarda gerçek kayıt yerine sesli taklit vardır.','Effects play only when tapped. Sirens are short representative sounds. Some animals use spoken imitations instead of recordings.')}</p><a class="setting-note" href="credits.html" target="_blank" rel="noopener">${t('Ses kaynakları','Sound credits')}</a></section>`);$('#effectEnabled').onchange=()=>{prefs.effects=$('#effectEnabled').checked;stopEffect();save()};$('#effectVolume').oninput=()=>{prefs.effectVolume=Number($('#effectVolume').value);save();if(playingEffect)playingEffect.volume=prefs.effectVolume}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopEffect()});
